"use client";

/**
 * Sound breakdown: a film plays in a frame above one lane per sound layer.
 * Each pass through the film adds layers, so the mix builds up in front of
 * the viewer: each lane draws its cues as waveforms, a playhead runs across,
 * and every cue lights in the primary colour while it sounds. The last pass
 * plays the full mix with the music.
 *
 * Written by Better Design. Painted from the theme prop. The sound files are CC0.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { type ReactNode, useMemo } from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig } from "remotion";
import {
  cueGain,
  cueStartFrame,
  easings,
  mixTrim,
  musicLevel,
  pickFont,
  progress,
  SFX_DATA,
  SFX_LAYER,
  type SoundCue,
  type SoundLayer,
  SOUND_LAYER_LABELS,
  SoundTrack,
  type VideoTheme,
  useVideoTheme,
  withAlpha,
} from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600"], subsets: ["latin"] });

/** One pass through the film: its title and the layers it adds to the ones already heard. */
export interface BreakdownStep {
  title: string;
  adds: SoundLayer[];
}

/** Build the mix in four passes: the interface, its pops, the motion and hits, then the music. */
export const DEFAULT_BREAKDOWN_STEPS: BreakdownStep[] = [
  { title: "Keys and clicks", adds: ["keys", "clicks"] },
  { title: "Add the pops", adds: ["pops"] },
  { title: "Add whooshes and hits", adds: ["whooshes", "hits"] },
  { title: "Full mix, with music", adds: ["music"] },
];

export interface SoundBreakdownProps {
  /** The film, drawn at its own size. It restarts on every pass. */
  children: ReactNode;
  /** The film's sound cues, on the film's clock. */
  cues: readonly SoundCue[];
  /** The film's length in frames. The breakdown runs this times the number of steps. */
  filmFrames: number;
  filmWidth?: number;
  filmHeight?: number;
  steps?: BreakdownStep[];
  /** Where the sound files are served. Defaults to better-design.com. */
  base?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

/** The layers heard on pass `step`: everything the steps up to it add. */
export const layersAt = (steps: readonly BreakdownStep[], step: number): SoundLayer[] =>
  steps.slice(0, step + 1).flatMap((s) => s.adds);

/** Composition length for a breakdown of a film `filmFrames` long. */
export const breakdownFrames = (filmFrames: number, steps: readonly BreakdownStep[] = DEFAULT_BREAKDOWN_STEPS): number => filmFrames * steps.length;

const PANEL_SCALE = 0.56;
const PANEL_TOP = 36;
const LANES_TOP = 712;
const LANE_H = 50;
const LANE_GAP = 6;
const TRACK_LEFT = 300;
const TRACK_RIGHT = 1860;
const TRACK_W = TRACK_RIGHT - TRACK_LEFT;
const BAR = 4;

/** The loudest point of a waveform across bar `i` of `count`, so a short attack never falls between two bars. */
function spanPeak(wave: readonly number[], i: number, count: number): number {
  const first = Math.floor((i / count) * wave.length);
  const last = Math.max(first + 1, Math.floor(((i + 1) / count) * wave.length));
  let peak = 0;
  for (let k = first; k < last && k < wave.length; k++) peak = Math.max(peak, wave[k]);
  return peak;
}

/**
 * A level as a bar height in [0, 1], on a 30 dB scale under the loudest
 * level in its lane, so quiet keys read as clearly as a loud hit does.
 */
const barHeight = (level: number, loudest: number): number =>
  Math.max(0, Math.min(1, (20 * Math.log10(Math.max(level, 1e-6) / Math.max(loudest, 1e-6)) + 30) / 30));

interface LaneProps {
  layer: SoundLayer;
  cues: readonly SoundCue[];
  local: number;
  filmFrames: number;
  fps: number;
  /** 0 hidden, 1 fully drawn: grows as the lane is revealed. */
  reveal: number;
  /** The lane was revealed on this pass. */
  fresh: boolean;
  allCues: readonly SoundCue[];
  trim: number;
  theme: VideoTheme;
}

function Lane({ layer, cues, local, filmFrames, fps, reveal, fresh, allCues, trim, theme }: LaneProps) {
  const x = (frame: number) => (frame / filmFrames) * TRACK_W;
  const bars: ReactNode[] = [];
  if (reveal <= 0) {
    // A lane not yet revealed stays empty: the viewer meets each layer when it is added.
  } else if (layer === "music") {
    const loop = SFX_DATA["music-bed"];
    const count = Math.floor(TRACK_W / BAR);
    const loudest = Math.max(...loop.wave) * musicLevel(-1e6, allCues, fps) * trim;
    for (let i = 0; i < count; i++) {
      const frame = (i / count) * filmFrames;
      const t = (frame / fps) % loop.duration;
      const level = loop.wave[Math.floor((t / loop.duration) * loop.wave.length)] * musicLevel(frame, allCues, fps) * trim;
      const h = barHeight(level, loudest) * (LANE_H - 10) * reveal;
      const lit = Math.abs(frame - local) < 3;
      bars.push(<rect key={i} x={i * BAR} y={(LANE_H - h) / 2} width={BAR - 1.5} height={h} rx={1} fill={lit ? theme.primary : withAlpha(theme.foreground, 0.42)} />);
    }
  } else {
    const loudest = Math.max(...cues.map((cue) => SFX_DATA[cue.sfx].peak * cueGain(cue) * trim));
    cues.forEach((cue, c) => {
      const data = SFX_DATA[cue.sfx];
      const start = cueStartFrame(cue, fps);
      const end = start + data.duration * fps;
      const sounding = local >= start && local <= end;
      const left = x(start);
      const width = Math.max(BAR, x(end) - left);
      const count = Math.max(1, Math.floor(width / BAR));
      for (let i = 0; i < count; i++) {
        const level = spanPeak(data.wave, i, count) * cueGain(cue) * trim;
        const h = Math.max(2, barHeight(level, loudest) * (LANE_H - 10) * reveal);
        bars.push(
          <rect key={`${c}-${i}`} x={left + i * BAR} y={(LANE_H - h) / 2} width={BAR - 1.5} height={h} rx={1}
            fill={sounding ? theme.primary : withAlpha(theme.foreground, 0.42)} />,
        );
      }
    });
  }
  const labelColor = reveal > 0 ? theme.foreground : withAlpha(theme.mutedForeground, 0.5);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, height: LANE_H, display: "flex", alignItems: "center" }}>
      <div style={{ width: TRACK_LEFT - 40, paddingLeft: 60, display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ width: 10, height: 10, borderRadius: 5, background: fresh ? theme.primary : reveal > 0 ? theme.foreground : withAlpha(theme.mutedForeground, 0.35) }} />
        <div style={{ fontSize: 24, fontWeight: 600, color: labelColor }}>{SOUND_LAYER_LABELS[layer]}</div>
      </div>
      <div style={{ position: "absolute", left: TRACK_LEFT, width: TRACK_W, height: LANE_H, borderRadius: theme.radius, background: withAlpha(theme.mutedForeground, reveal > 0 ? 0.08 : 0.04), overflow: "hidden" }}>
        <svg width={TRACK_W} height={LANE_H} style={{ display: "block" }}>{bars}</svg>
      </div>
    </div>
  );
}

/** A film above its sound, built up one pass at a time. */
export function SoundBreakdown({
  children,
  cues,
  filmFrames,
  filmWidth = 1920,
  filmHeight = 1080,
  steps = DEFAULT_BREAKDOWN_STEPS,
  base,
  theme: themeOverride,
  font,
}: SoundBreakdownProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const step = Math.min(steps.length - 1, Math.floor(frame / filmFrames));
  const local = frame - step * filmFrames;
  const heard = layersAt(steps, step);
  const lanes = steps.flatMap((s) => s.adds);
  const trim = useMemo(() => mixTrim(cues, fps, filmFrames, true), [cues, fps, filmFrames]);
  const panelW = filmWidth * PANEL_SCALE;
  const panelH = filmHeight * PANEL_SCALE;
  const titleIn = easings.out(progress(local, 0, 14));
  const playX = TRACK_LEFT + (local / filmFrames) * TRACK_W;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family }}>
      {steps.map((s, k) => (
        <Sequence key={k} from={k * filmFrames} durationInFrames={filmFrames} layout="none">
          <SoundTrack cues={cues} layers={layersAt(steps, k)} music base={base} durationInFrames={filmFrames} />
        </Sequence>
      ))}

      <div style={{ position: "absolute", left: (1920 - panelW) / 2, top: PANEL_TOP, width: panelW, height: panelH, borderRadius: theme.radius * 1.5, overflow: "hidden", border: `1px solid ${theme.border}`, boxShadow: `0 40px 80px -50px ${withAlpha(theme.foreground, 0.4)}` }}>
        <div style={{ width: filmWidth, height: filmHeight, transform: `scale(${PANEL_SCALE})`, transformOrigin: "0 0", position: "relative" }}>
          {steps.map((_, k) => (
            <Sequence key={k} from={k * filmFrames} durationInFrames={filmFrames}>
              {children}
            </Sequence>
          ))}
        </div>
      </div>

      <div style={{ position: "absolute", left: 60, top: LANES_TOP - 64, display: "flex", alignItems: "baseline", gap: 18, opacity: titleIn, transform: `translateY(${(1 - titleIn) * 12}px)` }}>
        <div style={{ fontSize: 22, fontWeight: 600, color: theme.primary, fontVariantNumeric: "tabular-nums" }}>{`${step + 1} / ${steps.length}`}</div>
        <div style={{ fontSize: 30, fontWeight: 600, color: theme.foreground, letterSpacing: "-0.01em" }}>{steps[step].title}</div>
      </div>

      {lanes.map((layer, i) => {
        const revealedAt = steps.findIndex((s) => s.adds.includes(layer));
        const fresh = revealedAt === step;
        const reveal = revealedAt < step ? 1 : fresh ? easings.out(progress(local, 4 + i * 2, 18)) : 0;
        return (
          <div key={layer} style={{ position: "absolute", left: 0, right: 0, top: LANES_TOP + i * (LANE_H + LANE_GAP) }}>
            <Lane layer={layer} cues={cues.filter((cue) => SFX_LAYER[cue.sfx] === layer)} local={local} filmFrames={filmFrames} fps={fps}
              reveal={heard.includes(layer) ? reveal : 0} fresh={fresh} allCues={cues} trim={trim} theme={theme} />
          </div>
        );
      })}

      <div style={{ position: "absolute", left: playX - 1, top: LANES_TOP - 14, width: 2, height: lanes.length * (LANE_H + LANE_GAP) + 8, background: theme.primary }} />
      <div style={{ position: "absolute", left: playX - 7, top: LANES_TOP - 20, width: 0, height: 0, borderLeft: "7px solid transparent", borderRight: "7px solid transparent", borderTop: `10px solid ${theme.primary}` }} />
    </AbsoluteFill>
  );
}
